package eventstore

import (
	"encoding/json"
	"os"
	"testing"
)

// The vector is generated by scripts/go-rewrite/gen-eventseq-vectors.mts, which
// runs the real Node agent for S02/S03/S04/S05/S13 and recovers the exact
// (type, sequenceNumber) of every appended event from its debug log, cross
// checked against the telemetry eventSeq values in go/testdata/traces/agent.
//
// The test feeds the ordered type list to the store and requires the assigned
// sequence numbers to match exactly. One session, one turn window, no eviction
// (a single turn never triggers it), so this exercises the numbering rule and
// the "every event consumes a number" property.
type eventSeqVector struct {
	Scenarios []struct {
		Scenario            string   `json:"scenario"`
		NormalizedOutSha256 string   `json:"normalizedOutSha256"`
		TransientTypes      []string `json:"transientTypes"`
		Events              []struct {
			Seq  int    `json:"seq"`
			Type string `json:"type"`
		} `json:"events"`
	} `json:"scenarios"`
}

// turnTags maps the transient event types to the single turn in each scenario.
// Non-transient session-scoped events carry no turn; that only matters for
// eviction, which this test does not trigger.
func loadEventSeqVector(t *testing.T) eventSeqVector {
	t.Helper()
	raw, err := os.ReadFile("../../testdata/vectors/agent-eventseq.json")
	if err != nil {
		t.Fatalf("read vector: %v", err)
	}
	var vec eventSeqVector
	if err := json.Unmarshal(raw, &vec); err != nil {
		t.Fatalf("parse vector: %v", err)
	}
	if len(vec.Scenarios) == 0 {
		t.Fatal("vector has no scenarios")
	}
	return vec
}

func TestAgentVectorSequenceNumbers(t *testing.T) {
	vec := loadEventSeqVector(t)
	for _, scenario := range vec.Scenarios {
		scenario := scenario
		t.Run(scenario.Scenario, func(t *testing.T) {
			store := NewInMemory(RetentionTurnWindow, nil)
			const session SessionID = "s"
			const turn = "t1"
			for _, want := range scenario.Events {
				got := store.Append(Event{SessionID: session, TurnID: turn, Type: want.Type})
				if got.SequenceNumber != want.Seq {
					t.Fatalf("seq %d: type %q got sequenceNumber %d, want %d",
						want.Seq, want.Type, got.SequenceNumber, want.Seq)
				}
			}
			if got := store.LatestSequenceNumber(session); got != len(scenario.Events) {
				t.Fatalf("latestSequenceNumber = %d, want %d", got, len(scenario.Events))
			}
			// Every event is retained within its own turn window, even the
			// transient ones.
			if got := len(store.Events(session)); got != len(scenario.Events) {
				t.Fatalf("retained events = %d, want %d", got, len(scenario.Events))
			}
		})
	}
}

// TestAgentVectorTypesAreKnown guards against a typo in the mirrored constants:
// every type in the vector must be one the store knows (named constant or at
// least a plausible contract value). It also proves the vector and the
// transient set agree on which types are evictable.
func TestAgentVectorTypesAreKnown(t *testing.T) {
	vec := loadEventSeqVector(t)
	seen := map[string]bool{}
	transient := map[string]bool{}
	for _, s := range vec.Scenarios {
		for _, tt := range s.TransientTypes {
			transient[tt] = true
		}
		for _, e := range s.Events {
			seen[e.Type] = true
		}
	}
	for typ := range seen {
		if IsTransient(typ) != transient[typ] {
			t.Errorf("transient mismatch for %q: store=%v vector=%v", typ, IsTransient(typ), transient[typ])
		}
	}
	// The scenarios must actually exercise transient and non-transient events.
	if len(transient) != 4 {
		t.Errorf("expected 4 transient types in vector, got %d", len(transient))
	}
}
